from pathlib import Path
a=Path(__file__).resolve().parent
def edit(name,changes):
    p=a/name;s=p.read_text(encoding='utf-8-sig')
    for old,new in changes:
        assert old in s,old
        s=s.replace(old,new)
    p.write_text(s,encoding='utf-8')
